22	// A Helm chart or a Kustomize overlay is validated after it is rendered
23	// (§3.80). Both renderers are optional: without them the directory is
24	// reported as not rendered, never as clean, and never as a missing tool —
25	// the schema stage did all it could.
26	//
27	// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
28	// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
29	// alpine/helm's entrypoint is `helm`, the kustomize image's is
30	// /app/kustomize, so in both the arguments follow the image name.
31	
32	// Default images for the two renderers.
33	const (
34		DefaultHelmImage      = "alpine/helm"
35		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
36	)
37	
38	// remoteBlockedHeadline is the title of a K8S-RENDER finding whose remote base the
39	// cut network refused. It replaces the generic one, which would end with
40	// kustomize's own first line: the message keeps the whole text.
41	const remoteBlockedHeadline = "Overlay does not build: remote base blocked"
42	
43	// uncheckedOverlayHeadline is the title of a K8S-RENDER finding for an overlay the gate
44	// could not judge, so that a native kustomize was not started on it (DEVDESK-771).
45	const uncheckedOverlayHeadline = "Overlay not built: its references could not be checked"
46	
47	// IDs of the findings the renderers themselves produce.
48	const (
49		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
50		HelmLintID = "HELM-LINT"
51		// K8sRenderID is a chart or an overlay that did not render at all.
52		K8sRenderID = "K8S-RENDER"
53	)
54	
55	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
56	// support.Message.Error formats it.
57	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
58	
59	// helmSourceLine is the comment helm template writes above each document,
60	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
61	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
62	
63	// renderScope is where a renderer runs. A binary runs in the target and sees
64	// the whole host. A container sees only mount, read-only at /scan, and works in
65	// the target inside it: mount is the target itself, or the git repository
66	// holding it, so an overlay or a chart can reach a sibling of the target as it
67	// does on the host (DEVDESK-742).
68	type renderScope struct {
69		target string
70		mount  string
71		// rel is the target relative to mount, with forward slashes; "" when the
72		// target is what is mounted.
73		rel string
74		// offline runs the renderer with the network cut (DEVDESK-767): a binary
75		// gets offlineEnviron, an image `--network none` and no proxy.
76		offline bool
77	}
78	
79	// cut is the scope with the network cut for the renderer that runs in it.
80	func (s renderScope) cut() renderScope {
81		s.offline = true
82		return s
83	}
84	
85	// targetOnly mounts the target and nothing else.
86	func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }
87	
88	// workdir is the target inside the container.
89	func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }
90	
91	// userHomeDir is the home directory the mount guard keeps out of reach. Tests
92	// swap it.
93	var userHomeDir = os.UserHomeDir
94	
95	// resolveRenderScope asks git, in the target, for the repository holding it.
96	// Without an answer (no git, not a repository), or when the repository's
97	// configuration moves its work tree elsewhere (core.worktree, which a cloned
98	// .git file can bring along), the target alone is mounted.
99	func resolveRenderScope(ctx context.Context, target string) renderScope {
100		git := func(args ...string) ([]byte, error) {
101			return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
102		}
103		out, err := git("rev-parse", "--show-toplevel")
104		if err != nil {
105			log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", logWord(target), logErr(err))
106			return targetOnly(target)
107		}
108		worktree, err := git("config", "--get", "core.worktree")
109		var exitErr *exitError
110		unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
111		if !unset {
112			log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
113				logWord(target), strings.TrimSpace(string(worktree)), logErr(err))
114			return targetOnly(target)
115		}
116		scope, ok := widerScope(target, strings.TrimSpace(string(out)))
117		if !ok {
118			return targetOnly(target)
119		}
120		log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", logWord(scope.mount), logWord(target))
121		return scope
122	}
123	
124	// gitEnviron is env without the variables that point git at another
125	// repository, work tree or configuration: the mount is decided by the target
126	// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
127	// repository earlier, and dropping it would widen what the user limited.
128	func gitEnviron(env []string) []string {
129		out := make([]string, 0, len(env))
130		for _, kv := range env {
131			name, _, _ := strings.Cut(kv, "=")
132			switch {
133			case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
134				strings.HasPrefix(name, "GIT_CONFIG"):
135				continue
136			}
137			out = append(out, kv)
138		}
139		return out
140	}
141	
142	// widerScope mounts top, the repository git named, when it is safe to: top is
143	// a strict ancestor of the target once symlinks are resolved, neither the
144	// filesystem root nor the home directory nor anything above it, and it holds
145	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
146	// included, keeps the target alone.
147	func widerScope(target, top string) (renderScope, bool) {
148		if top == "" || !filepath.IsAbs(top) {
149			return renderScope{}, false
150		}
151		root, err := filepath.EvalSymlinks(top)
152		if err != nil {
153			return renderScope{}, false
154		}
155		real, err := filepath.EvalSymlinks(target)
156		if err != nil {
157			return renderScope{}, false
158		}
159		rel, err := filepath.Rel(root, real)
160		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
161			return renderScope{}, false
162		}
163		if filepath.Dir(root) == root {
164			return renderScope{}, false
165		}
166		home, err := userHomeDir()
167		if err != nil || home == "" {
168			return renderScope{}, false
169		}
170		if h, err := filepath.EvalSymlinks(home); err == nil {
171			home = h
172		}
173		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
174			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
175			return renderScope{}, false
176		}
177		if !gitDirIsHere(root) {
178			return renderScope{}, false
179		}
180		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
181	}
182	
183	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
184	// one line, a path.
185	const maxGitFile = 4096
186	
187	// gitDirIsHere reports whether root holds its repository's .git: a directory,
188	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
189	// root's .git back in its own gitdir file. A symlink, a file that says
190	// anything else, or a git directory that does not point back is refused: git
191	// was then told where the work tree is, rather than finding it.
192	func gitDirIsHere(root string) bool {
193		dotGit := filepath.Join(root, ".git")
194		info, err := os.Lstat(dotGit)
195		if err != nil {
196			return false
197		}
198		if info.IsDir() {
199			return true
200		}
201		if !info.Mode().IsRegular() {
202			return false
203		}
204		line, ok := readGitFile(dotGit)
205		gitDir, found := strings.CutPrefix(line, "gitdir: ")
206		if !ok || !found {
207			return false
208		}
209		if !filepath.IsAbs(gitDir) {
210			gitDir = filepath.Join(root, gitDir)
211		}
212		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
213		if !ok {
214			return false
215		}
216		if !filepath.IsAbs(back) {
217			back = filepath.Join(gitDir, back)
218		}
219		a, errA := filepath.EvalSymlinks(back)
220		b, errB := filepath.EvalSymlinks(dotGit)
221		return errA == nil && errB == nil && a == b
222	}
223	
224	// readGitFile reads the one line of a small regular file.
225	func readGitFile(p string) (string, bool) {
226		info, err := os.Lstat(p)
227		if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
228			return "", false
229		}
230		data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
231		if err != nil {
232			return "", false
233		}
234		return strings.TrimSpace(string(data)), true
235	}
236	
237	// renderer runs one tool in the repository, the way every other tool runs:
238	// in the target for a binary; for an image, with the scope's mount read-only
239	// at /scan and the target inside it as the working directory.
240	func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
241		// helm gets them on lint and on template alike: only the flags the two
242		// share (--values, --set…) make sense there.
243		args = afterSubcommand(args, tool.Args)
244		if tool.Source != ToolSourceContainer {
245			name := tool.Binary
246			if name == "" {
247				name = binary
248			}
249			cmd := toolCmd{Name: name, Args: args, Dir: scope.target}
250			if scope.offline {
251				cmd.Env = offlineEnviron(os.Environ())
252			}
253			return cmd
254		}
255		return containerRun{
256			Flags:   []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
257			Image:   orDefault(tool.Image, defaultImage),
258			Argv:    args,
259			Offline: scope.offline,
260		}.cmd()
261	}
262	
263	func orDefault(v, def string) string {
264		if v == "" {
265			return def
266		}
267		return v
268	}
269	
270	// renderRepro is the Repro line of a renderer run on target (a chart or an
271	// overlay directory), run from the scanned directory like the scan did. The
272	// user's arguments are left out: they may hold a secret (--set password=REDACTED
273	func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
274		return localRepro(tool, name, []string{sub}, target)
275	}
276	
277	func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
278		return renderer(scope, tool, DefaultHelmImage, "helm", sub, asPathArg(chart))
279	}
280	
281	func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
282		return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", asPathArg(dir))
283	}
284	
285	// asPathArg is dir as a positional argument of helm or kustomize. The folder's
286	// name comes from the repository being scanned, and two kinds of name are not
287	// read as the local folder it is (DEVDESK-763): one that starts with "-"
288	// (--load-restrictor=LoadRestrictionsNone, -x) is read as an option, and
289	// kustomize reads an ordinary one such as github.com/org/repo or
290	// git@host:o/r as a remote git base and runs git fetch even when the folder
291	// exists. "./" makes every relative folder a local path whatever the tool and
292	// wherever the user's own arguments land. "." and an absolute path already are
293	// one, and a name that already starts with "./" is left alone. Only the
294	// argument is changed: the findings, their steps and the Repro keep the
295	// folder's own name.
296	func asPathArg(dir string) string {
297		if dir == "." || strings.HasPrefix(dir, "./") || filepath.IsAbs(dir) || strings.HasPrefix(dir, "/") {
298			return dir
299		}
300		return "./" + dir
301	}
302	
303	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
304	// and no repository mount: it reads nothing but its input and its cache.
305	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
306		flags := kubeconformFlags(tool, opts)
307		if tool.Source != ToolSourceContainer {
308			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
309		}
310		engineArgs := []string{"-i"}
311		if opts.CacheDir != "" {
312			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
313		}
314		return containerRun{
315			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
316		}.cmd()
317	}
318	
319	// k8sValidation is one schema stage over one repository: the tools it has,
320	// what it validates against, and the report it fills in.
321	type k8sValidation struct {
322		target string
323		// scope is where helm and kustomize run, resolved once per stage.
324		scope renderScope
325		// gateRoot is the limit of the paths the native kustomize gate follows,
326		// resolved once and only when a native kustomize is about to be gated.
327		gateRoot    string
328		gateRun     gateRun
329		kubeconform ToolSpec
330		opts        KubeconformOptions
331		report      *KubeconformReport
332	}
333	
334	// available reports whether an optional renderer was resolved at all.
335	func available(tool ToolSpec) bool {
336		return tool.Source != ToolSourceNone && tool.Source != ""
337	}
338	
339	// renderCharts lints, renders and validates each chart. Without helm, every
340	// chart is reported as not rendered.
341	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
342		tool := v.opts.Helm
343		for _, chart := range charts {
344			if !available(tool) {
345				v.report.Unrendered = append(v.report.Unrendered, chart)
346				continue
347			}
348			// helm reads no remote base, so it never has the network.
349			scope := v.scope.cut()
350			lint := helmLint(ctx, scope, chart, tool)
351			v.report.Findings = append(v.report.Findings, lint...)
352	
353			cmd := helmArgs(scope, chart, tool, "template")
354			log.Printf("Running: %s", cmd.Loggable())
355			rendered, err := runner.Run(ctx, cmd, nil)
356			if err != nil {
357				if ctx.Err() != nil {
358					return ctx.Err()
359				}
360				// helm lint renders the chart too, so a chart that does not
361				// render has usually been reported by it already, with more to
362				// say. The render failure is the fallback, not a second copy.
363				if !hasError(lint) {
364					repro, from := renderRepro(tool, "helm", "template", chart)
365					v.report.Findings = append(v.report.Findings,
366						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", from,
367							renderSteps(SourceHelm, chart, from, failureDetail(err), false), repro, err))
368				}
369				continue
370			}
371			origins := helmOrigins(rendered, chart)
372			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
373				if file, ok := origins[kind+"/"+name]; ok {
374					return file
375				}
376				return chart
377			})
378			if err != nil {
379				return fmt.Errorf("chart %s: %w", chart, err)
380			}
381		}
382		return nil
383	}
384	
385	// renderKustomizations builds and validates each overlay. Without kustomize,
386	// every overlay is reported as not rendered.
387	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
388		tool := v.opts.Kustomize
389		for _, dir := range dirs {
390			if !available(tool) {
391				v.report.Unrendered = append(v.report.Unrendered, dir)
392				continue
393			}
394			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
395			scope := v.scope
396			if !v.opts.AllowRemoteBases {
397				scope = scope.cut()
398			}
399			// Go never applies a proxy to the loopback, so a native kustomize with the
400			// network cut can still reach a service of this machine: the overlay is
401			// read first and kustomize is not started unless every reference is local
402			// (DEVDESK-771). From an image the engine cuts the network.
403			if scope.offline && tool.Source != ToolSourceContainer {
404				root, run := v.gateScope(ctx)
405				verdict := vetOverlayIn(ctx, root, filepath.Join(v.target, filepath.FromSlash(dir)), defaultGateLimits, run)
406				if verdict.Kind != gateOK {
407					if ctx.Err() != nil {
408						return ctx.Err()
409					}
410					log.Printf("[scan/k8s] overlay %q not built: %s, %q", dir, logWord(verdict.Kind.String()), verdict.Reason)
411					v.report.Findings = append(v.report.Findings, gateFinding(dir, file, verdict, tool.Source))
412					continue
413				}
414			}
415			cmd := kustomizeArgs(scope, dir, tool)
416			log.Printf("Running: %s", cmd.Loggable())
417			rendered, err := runner.Run(ctx, cmd, nil)
418			if err != nil {
419				if ctx.Err() != nil {
420					return ctx.Err()
421				}
422				repro, from := renderRepro(tool, "kustomize", "build", dir)
423				detail := failureDetail(err)
424				blocked := scope.offline && remoteBlocked(detail, from)
425				f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
426					renderSteps(SourceKustomize, dir, from, detail, blocked), repro, err)
427				if blocked {
428					markRemoteBlocked(&f)
429				}
430				v.report.Findings = append(v.report.Findings, f)
431				continue
432			}
433			// kustomize adds no origin to what it emits unless the kustomization
434			// asks for it, and DevDesk does not write into the file to ask. The
435			// overlay is what was built, so it is what a finding points at.
436			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
437			if err != nil {
438				return fmt.Errorf("overlay %s: %w", dir, err)
439			}
440		}
441		return nil
442	}
443	
444	// gateScope is the limit of the paths the kustomize gate follows, the git
445	// repository holding the target or the target itself without one, and what the
446	// gate remembers across the overlays of this scan. git is asked once, the first
447	// time a native kustomize is gated.
448	func (v *k8sValidation) gateScope(ctx context.Context) (string, gateRun) {
449		if v.gateRoot == "" {
450			scope := resolveRenderScope(ctx, v.target)
451			v.gateRoot = scope.mount
452			v.gateRun = gateRun{cache: &gateCache{}, limit: "the repository"}
453			if scope.rel == "" {
454				v.gateRun.limit = "the scanned folder"
455			}
456		}
457		return v.gateRoot, v.gateRun
458	}
459	
460	// markRemoteBlocked gives a K8S-RENDER finding the words of a remote base the
461	// cut network refused, whether kustomize said so or the gate did. A copied
462	// `kustomize build` would run the refused fetch again, with the user's ssh agent
463	// and proxy, on a repository that is not trusted, so there is no Repro.
464	func markRemoteBlocked(f *Finding) {
465		f.Title = remoteBlockedHeadline
466		f.Resolution = remoteBlockedResolution
467		f.Repro = ""
468	}
469	
470	// gateFinding is the K8S-RENDER finding of an overlay the gate refused, so that
471	// kustomize was not started: a reference that is not local gets the finding of a
472	// blocked remote base, an overlay that could not be judged one of its own.
473	func gateFinding(dir, file string, v gateVerdict, from ToolSource) Finding {
474		if v.Kind == gateRemote {
475			f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
476				renderSteps(SourceKustomize, dir, from, "", true), "", errors.New(remoteMessage(v)))
477			markRemoteBlocked(&f)
478			return f
479		}
480		f := renderFailure(SourceKustomize, "kustomize", file, "Overlay not built", from,
481			uncheckedOverlaySteps(dir, v.Reason), "", errors.New(uncheckedMessage(dir, v)))
482		f.Title = uncheckedOverlayHeadline
483		f.Resolution = uncheckedResolution
484		return f
485	}
486	
487	// remoteMessage says where the reference is, what it is and why it is refused,
488	// each name as %q: the text is the repository's own.
489	func remoteMessage(v gateVerdict) string {
490		return fmt.Sprintf("DevDesk did not run kustomize: the field %q of %q holds %q, which is not a path of this repository (%s).",
491			clip(v.Field), clip(v.File), clip(v.Ref), clip(v.Reason))
492	}
493	
494	// uncheckedMessage says what could not be checked, in which file and field.
495	func uncheckedMessage(dir string, v gateVerdict) string {
496		msg := fmt.Sprintf("DevDesk did not run kustomize: the references of the overlay %q could not be checked", clip(dir))
497		if v.File != "" {
498			msg += fmt.Sprintf(", in %q", clip(v.File))
499		}
500		if v.Field != "" {
501			msg += fmt.Sprintf(" (field %q)", clip(v.Field))
502		}
503		return msg + ": " + clip(v.Reason) + "."
504	}
505	
506	// validateRendered runs kubeconform over rendered YAML and points each
507	// finding back at the file it came from. A rendered line is not a line of
508	// any file in the repository, so these findings carry none.
509	func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
510		if len(bytes.TrimSpace(rendered)) == 0 {
511			return nil
512		}
513		cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
514		log.Printf("Running: %s", cmd.Loggable())
515		out, err := runner.Run(ctx, cmd, nil)
516		if err := kubeconformFailure(out, err); err != nil {
517			return err
518		}
519		noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
520		findings, skipped, err := parseKubeconformReport(out, v.opts.KubernetesVersion, noFile, origin, dialect)
521		if err != nil {
522			return err
523		}
524		v.report.SkippedCustom += skipped
525		for i := range findings {
526			findings[i].IaCType = dialect
527		}
528		v.report.Findings = append(v.report.Findings, findings...)
529		return nil
530	}
531	
532	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
533	// when a chart fails; its messages are still the answer. A run that printed
534	// nothing parseable is logged and yields nothing — the render that follows
535	// will say whether the chart is usable.
536	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
537		cmd := helmArgs(scope, chart, tool, "lint")
538		log.Printf("Running: %s", cmd.Loggable())
539		out, err := runner.Run(ctx, cmd, nil)
540		findings, recognised := parseHelmLint(out, chart, scope)
541		if err != nil && !recognised {
542			log.Printf("ERROR [scan/helm] lint %s: %v", logWord(chart), logErr(err))
543		}
544		repro, from := renderRepro(tool, "helm", "lint", chart)
545		for i := range findings {
546			findings[i].Repro, findings[i].RanFrom = repro, from
547		}
548		return findings
549	}
550	
551	// parseHelmLint turns helm lint's text into findings. The second result says
552	// the output was helm lint's at all.
553	//
554	// A message's path is usually relative to the chart ("templates/cm.yaml"),
555	// but not always: the missing-dependency warning names the chart directory
556	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
557	// Both are brought back to a path relative to the target.
558	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
559		file := func(p string) string { return helmLintPath(p, chart, scope) }
560		var findings []Finding
561		recognised := false
562		sc := bufio.NewScanner(bytes.NewReader(out))
563		for sc.Scan() {
564			line := strings.TrimSpace(sc.Text())
565			switch {
566			case strings.HasPrefix(line, "==> Linting"):
567				recognised = true
568			case strings.HasPrefix(line, "Error "):
569				// Printed instead of the messages when the chart could not be
570				// loaded at all.
571				recognised = true
572				findings = append(findings, helmLintFinding(chart, chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
573			default:
574				m := helmLintLine.FindStringSubmatch(line)
575				if m == nil {
576					continue
577				}
578				recognised = true
579				switch m[1] {
580				case "ERROR":
581					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityHigh, m[3]))
582				case "WARNING":
583					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityLow, m[3]))
584				}
585			}
586		}
587		return findings, recognised
588	}
589	
590	// helmLintPath resolves a path helm lint printed to one relative to the
591	// target. In a container the target is the scope's working directory, which is
592	// /scan itself unless the git repository around the target is mounted.
593	func helmLintPath(p, chart string, scope renderScope) string {
594		p = strings.TrimSuffix(p, "/")
595		switch {
596		case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
597			if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
598				return filepath.ToSlash(rel)
599			}
600			return p
601		case filepath.IsAbs(p):
602			if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
603				return filepath.ToSlash(rel)
604			}
605			return filepath.ToSlash(p)
606		default:
607			return path.Join(chart, p)
608		}
609	}
