611	func helmLintFinding(chart, file string, severity SeverityLevel, msg string) Finding {
612		return Finding{
613			Steps:       helmLintSteps(file, chart),
614			ID:          HelmLintID,
615			Title:       msg,
616			Description: "helm lint reported this about the chart.",
617			Message:     msg,
618			Severity:    severity,
619			Source:      SourceHelm,
620			File:        file,
621			IaCType:     "helm",
622		}
623	}
