634	// renderFailure is a chart or an overlay that could not be rendered: nothing
635	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
636	// same way.
637	//
638	// steps and repro are what the caller wrote for it (renderSteps, localRepro);
639	// from is where the renderer ran.
640	func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {
641		detail := failureDetail(err)
642		first, _, _ := strings.Cut(detail, "\n")
643		return Finding{
644			ID:          K8sRenderID,
645			Title:       title + ": " + first,
646			Description: "The directory could not be rendered, so none of its resources were validated.",
647			Message:     detail,
648			Resolution:  renderResolution(source, from, detail),
649			Steps:       steps,
650			Repro:       repro,
651			RanFrom:     from,
652			Severity:    SeverityHigh,
653			Source:      source,
654			File:        file,
655			IaCType:     dialect,
656		}
657	}
