339	// renderCharts lints, renders and validates each chart. Without helm, every
340	// chart is reported as not rendered.
341	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
342		tool := v.opts.Helm
343		for _, chart := range charts {
344			if !available(tool) {
345				v.report.Unrendered = append(v.report.Unrendered, chart)
346				continue
347			}
348			// helm reads no remote base, so it never has the network.
349			scope := v.scope.cut()
350			lint := helmLint(ctx, scope, chart, tool)
351			v.report.Findings = append(v.report.Findings, lint...)
352	
353			cmd := helmArgs(scope, chart, tool, "template")
354			log.Printf("Running: %s", cmd.Loggable())
355			rendered, err := runner.Run(ctx, cmd, nil)
356			if err != nil {
357				if ctx.Err() != nil {
358					return ctx.Err()
359				}
360				// helm lint renders the chart too, so a chart that does not
361				// render has usually been reported by it already, with more to
362				// say. The render failure is the fallback, not a second copy.
363				if !hasError(lint) {
364					repro, from := renderRepro(tool, "helm", "template", chart)
365					v.report.Findings = append(v.report.Findings,
366						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", from,
367							renderSteps(SourceHelm, chart, from, failureDetail(err), false), repro, err))
368				}
369				continue
370			}
371			origins := helmOrigins(rendered, chart)
372			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
373				if file, ok := origins[kind+"/"+name]; ok {
374					return file
375				}
376				return chart
377			})
378			if err != nil {
379				return fmt.Errorf("chart %s: %w", chart, err)
380			}
381		}
382		return nil
383	}
