385	// renderKustomizations builds and validates each overlay. Without kustomize,
386	// every overlay is reported as not rendered.
387	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
388		tool := v.opts.Kustomize
389		for _, dir := range dirs {
390			if !available(tool) {
391				v.report.Unrendered = append(v.report.Unrendered, dir)
392				continue
393			}
394			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
395			scope := v.scope
396			if !v.opts.AllowRemoteBases {
397				scope = scope.cut()
398			}
399			// Go never applies a proxy to the loopback, so a native kustomize with the
400			// network cut can still reach a service of this machine: the overlay is
401			// read first and kustomize is not started unless every reference is local
402			// (DEVDESK-771). From an image the engine cuts the network.
403			if scope.offline && tool.Source != ToolSourceContainer {
404				root, run := v.gateScope(ctx)
405				verdict := vetOverlayIn(ctx, root, filepath.Join(v.target, filepath.FromSlash(dir)), defaultGateLimits, run)
406				if verdict.Kind != gateOK {
407					if ctx.Err() != nil {
408						return ctx.Err()
409					}
410					log.Printf("[scan/k8s] overlay %q not built: %s, %q", dir, logWord(verdict.Kind.String()), verdict.Reason)
411					v.report.Findings = append(v.report.Findings, gateFinding(dir, file, verdict, tool.Source))
412					continue
413				}
414			}
415			cmd := kustomizeArgs(scope, dir, tool)
416			log.Printf("Running: %s", cmd.Loggable())
417			rendered, err := runner.Run(ctx, cmd, nil)
418			if err != nil {
419				if ctx.Err() != nil {
420					return ctx.Err()
421				}
422				repro, from := renderRepro(tool, "kustomize", "build", dir)
423				detail := failureDetail(err)
424				blocked := scope.offline && remoteBlocked(detail, from)
425				f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
426					renderSteps(SourceKustomize, dir, from, detail, blocked), repro, err)
427				if blocked {
428					markRemoteBlocked(&f)
429				}
430				v.report.Findings = append(v.report.Findings, f)
431				continue
432			}
433			// kustomize adds no origin to what it emits unless the kustomization
434			// asks for it, and DevDesk does not write into the file to ask. The
435			// overlay is what was built, so it is what a finding points at.
436			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
437			if err != nil {
438				return fmt.Errorf("overlay %s: %w", dir, err)
439			}
440		}
441		return nil
442	}
