444	// gateScope is the limit of the paths the kustomize gate follows, the git
445	// repository holding the target or the target itself without one, and what the
446	// gate remembers across the overlays of this scan. git is asked once, the first
447	// time a native kustomize is gated.
448	func (v *k8sValidation) gateScope(ctx context.Context) (string, gateRun) {
449		if v.gateRoot == "" {
450			scope := resolveRenderScope(ctx, v.target)
451			v.gateRoot = scope.mount
452			v.gateRun = gateRun{cache: &gateCache{}, limit: "the repository"}
453			if scope.rel == "" {
454				v.gateRun.limit = "the scanned folder"
455			}
456		}
457		return v.gateRoot, v.gateRun
458	}
