487	// remoteMessage says where the reference is, what it is and why it is refused,
488	// each name as %q: the text is the repository's own.
489	func remoteMessage(v gateVerdict) string {
490		return fmt.Sprintf("DevDesk did not run kustomize: the field %q of %q holds %q, which is not a path of this repository (%s).",
491			clip(v.Field), clip(v.File), clip(v.Ref), clip(v.Reason))
492	}
