494	// uncheckedMessage says what could not be checked, in which file and field.
495	func uncheckedMessage(dir string, v gateVerdict) string {
496		msg := fmt.Sprintf("DevDesk did not run kustomize: the references of the overlay %q could not be checked", clip(dir))
497		if v.File != "" {
498			msg += fmt.Sprintf(", in %q", clip(v.File))
499		}
500		if v.Field != "" {
501			msg += fmt.Sprintf(" (field %q)", clip(v.Field))
502		}
503		return msg + ": " + clip(v.Reason) + "."
504	}
