532	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
533	// when a chart fails; its messages are still the answer. A run that printed
534	// nothing parseable is logged and yields nothing — the render that follows
535	// will say whether the chart is usable.
536	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
537		cmd := helmArgs(scope, chart, tool, "lint")
538		log.Printf("Running: %s", cmd.Loggable())
539		out, err := runner.Run(ctx, cmd, nil)
540		findings, recognised := parseHelmLint(out, chart, scope)
541		if err != nil && !recognised {
542			log.Printf("ERROR [scan/helm] lint %s: %v", logWord(chart), logErr(err))
543		}
544		repro, from := renderRepro(tool, "helm", "lint", chart)
545		for i := range findings {
546			findings[i].Repro, findings[i].RanFrom = repro, from
547		}
548		return findings
549	}
