659	// failureDetail is what a renderer printed when it failed, or the error itself.
660	func failureDetail(err error) string {
661		var exitErr *exitError
662		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
663			return strings.TrimSpace(exitErr.Stderr)
664		}
665		return err.Error()
666	}
