668	// How to fix a chart or an overlay that does not render, in the renderer's own
669	// terms.
670	const (
671		helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
672			"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
673		// remoteBlockedResolution is for an overlay whose remote base was refused
674		// because the render runs with the network cut (DEVDESK-767).
675		remoteBlockedResolution = "The overlay names a remote base (a git URL or an https resource) and DevDesk " +
676			"renders a repository it does not trust with the network cut. Copy the base into the repository " +
677			"and reference it by a relative path, or, for a repository you trust, set " +
678			"scan.tools.kustomize.allow_remote_bases: true, which also lets the overlay reach the services of " +
679			"this machine (its loopback)."
680		// uncheckedResolution is for an overlay DevDesk did not build because it could
681		// not check every reference in it (DEVDESK-771): kustomize is not started on
682		// what it cannot judge.
683		uncheckedResolution = "DevDesk reads an overlay before building it and builds it only when every reference " +
684			"in it, and in what it pulls in, is a path of the repository. Remove what it could not read, or build " +
685			"the overlay in a container (scan.tools.kustomize.source: image), which has no network, or, for a " +
686			"repository you trust, set scan.tools.kustomize.allow_remote_bases: true, which also lets the overlay " +
687			"reach the services of this machine (its loopback)."
688		kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
689		// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
690		// refuses a file outside the kustomization's directory, with this message.
691		// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
692		// `build` (afterSubcommand), where kustomize accepts it.
693		loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
694			"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
695			"or, if your deployment tool allows it, set " +
696			"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
697	)
698	
699	// mountResolution is added for a kustomize image that could not find a path:
700	// the container sees only what DevDesk mounts (renderScope), and DevDesk does
701	// not walk the repository to tell a hidden reference from a broken one.
702	// ToolConfig's `source` key takes auto, binary or image.
703	const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
704		"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
705		"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."
