707	// renderResolution picks the advice for a render failure from the renderer,
708	// where it ran and what it printed.
709	func renderResolution(source string, from ToolSource, detail string) string {
710		if source != SourceKustomize {
711			return helmRenderResolution
712		}
713		advice := kustomizeRenderResolution
714		if isLoadRestrictor(detail) {
715			advice = loadRestrictorResolution
716		}
717		if from == ToolSourceContainer &&
718			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
719			advice += " " + mountResolution
720		}
721		return advice
722	}
