724	// helmOrigins maps each rendered resource, by kind and name, to the template
725	// it came from, relative to the repository. helm names the template under the
726	// chart's own name, which need not be its directory's.
727	func helmOrigins(rendered []byte, chart string) map[string]string {
728		origins := map[string]string{}
729		for _, doc := range splitYAMLDocuments(rendered) {
730			var source string
731			for _, line := range strings.Split(doc, "\n") {
732				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
733					source = m[1]
734					break
735				}
736			}
737			if source == "" {
738				continue
739			}
740			var meta struct {
741				Kind     string `yaml:"kind"`
742				Metadata struct {
743					Name string `yaml:"name"`
744				} `yaml:"metadata"`
745			}
746			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
747				continue
748			}
749			key := meta.Kind + "/" + meta.Metadata.Name
750			if _, seen := origins[key]; seen {
751				continue
752			}
753			_, rest, _ := strings.Cut(source, "/")
754			origins[key] = path.Join(chart, rest)
755		}
756		return origins
757	}
758	
759	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
760	func splitYAMLDocuments(stream []byte) []string {
761		var docs []string
762		var cur strings.Builder
763		r := bufio.NewReader(bytes.NewReader(stream))
764		for {
765			line, err := r.ReadString('\n')
766			if strings.TrimRight(line, "\r\n") == "---" {
767				docs = append(docs, cur.String())
768				cur.Reset()
769			} else {
770				cur.WriteString(line)
771			}
772			if errors.Is(err, io.EOF) || err != nil {
773				break
774			}
775		}
776		return append(docs, cur.String())
777	}
