//go:build flux_red

package scan

// TODO(coder, DEVDESK-783): remove the `flux_red` build tag above (the first line
// of this file) and the one of kustomize_flux_fifo_red_test.go as soon as these
// exist:
//
//   - kustomize_flux.go: func fluxOverlay(root, overlay string, lim gateLimits) bool
//   - kubeconform_render.go: func kustomizeArgs(scope renderScope, dir string, tool ToolSpec, loadAnywhere bool) toolCmd
