	"io"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

func fluxOverlay(root, overlay string, lim gateLimits) bool {
	root, err := filepath.Abs(root)
	if err != nil {
		return false
	}
	if root, err = filepath.EvalSymlinks(root); err != nil {
		return false
	}
	if overlay, err = filepath.Abs(overlay); err != nil {
		return false
	}
	real, err := filepath.EvalSymlinks(overlay)
	if err != nil || !within(root, real) {
		return false
	}
	g := &gate{ctx: context.Background(), root: root, lim: lim, visited: map[string]bool{}, limit: "the repository"}
	file, _ := g.kustomizationFile(real)
	if file == "" {
		return false
	}
	if target, err := filepath.EvalSymlinks(file); err != nil || !within(root, target) {
		return false
	}
	node, reason := g.readYAML(file)
	if reason != "" {
		return false
	}
	for _, field := range []string{"resources", "bases"} {
		list := mapGet(node, field)
		if list == nil || list.Kind != yaml.SequenceNode {
			continue
		}
		for _, e := range list.Content {
			if e.Kind != yaml.ScalarNode || e.Tag != "!!str" {
				continue
			}
			if ok, _ := localRef(e.Value); !ok {
				continue
			}
			cand := filepath.Join(real, filepath.FromSlash(e.Value))
			if !within(root, cand) {
				continue
			}
			rp, err := filepath.EvalSymlinks(cand)
			if err != nil || !within(root, rp) {
				continue
			}
			data, reason := readGateFile(rp, lim.FileBytes)
			if reason != "" {
				continue
			}
			if fluxDocs(data) {
				return true
			}
		}
	}
	return false
}

func fluxDocs(data []byte) bool {
	dec := yaml.NewDecoder(strings.NewReader(string(data)))
	for {
		var doc yaml.Node
		if err := dec.Decode(&doc); err != nil {
			if errors.Is(err, io.EOF) {
				return false
			}
			return false
		}
		if doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 {
			continue
		}
		av := mapGet(doc.Content[0], "apiVersion")
		if av == nil || av.Kind != yaml.ScalarNode {
			continue
		}
		group, _, _ := strings.Cut(av.Value, "/")
		if strings.HasSuffix(group, ".toolkit.fluxcd.io") && len(group) > len(".toolkit.fluxcd.io") {
			return true
		}
	}
}

func userSetsLoadRestrictor(args []string) bool {
	for _, a := range args {
		if strings.HasPrefix(a, "--load-restrictor") {
			return true
		}
	}
	return false
}

